function zombie_form(pm)

{
    switch (pm.mlet) {
    case C.S_ZOMBIE: /* when already a zombie/ghoul/skeleton, will stay as is */
        return C.int(C.NON_PM);
    case C.S_KOBOLD:
        return C.int(C.PM_KOBOLD_ZOMBIE);
    case C.S_ORC:
        return C.int(C.PM_ORC_ZOMBIE);
    case C.S_GIANT:
        if (C.samePtr(pm, C.mons[C.PM_ETTIN]))
            return C.int(C.PM_ETTIN_ZOMBIE);
        return C.int(C.PM_GIANT_ZOMBIE);
    case C.S_HUMAN:
    case C.S_KOP:
        if (C.is_elf(pm))
            return C.int(C.PM_ELF_ZOMBIE);
        return C.int(C.PM_HUMAN_ZOMBIE);
    case C.S_HUMANOID:
        if (C.is_dwarf(pm))
            return C.int(C.PM_DWARF_ZOMBIE);
        else
            break;
    case C.S_GNOME:
        return C.int(C.PM_GNOME_ZOMBIE);
    }
    return C.int(C.NON_PM);
}

