    if ((((C.int((C.svm.mvitals[mndx].mvflags) & (C.G_GENOD)) != 0) || ((!C.samePtr(mon.data, C.mons[mon.cham]) && !C.rn2(4, 4975, "pickvampshape")) ? 1 : 0)) ? 1 : 0))
        return C.int(mon.cham);

