/* kill all members of genocided species */
function kill_genocided_monsters()

{
    let mtmp, mtmp2;
    let kill_cham;
    let mndx;

    /*
     * Called during genocide, and again upon level change.  The latter
     * catches up with any migrating monsters as they finally arrive at
     * their intended destinations, so possessions get deposited there.
     *
     * Chameleon handling:
     *  1) if chameleons have been genocided, destroy them
     *     regardless of current form;
     *  2) otherwise, force every chameleon which is imitating
     *     any genocided species to take on a new form.
     */
    for ((mtmp = C.fmon); mtmp; (mtmp = mtmp2)) {
        (mtmp2 = mtmp.nmon);
        if (C.DEADMONSTER(mtmp))
            continue;
        (mndx = C.int(C.monsndx(mtmp.data)));
        (kill_cham = C.char(((C.ismnum(mtmp.cham) && C.int((C.svm.mvitals[mtmp.cham].mvflags) & (C.G_GENOD))) ? 1 : 0)));
        if (((C.int((C.svm.mvitals[mndx].mvflags) & (C.G_GENOD)) || kill_cham) ? 1 : 0)) {
            if (((C.ismnum(mtmp.cham) && !kill_cham) ? 1 : 0))
                newcham(mtmp, 0, C.NC_SHOW_MSG);
            else
                mondead(mtmp);
        }
        if (mtmp.minvent)
            kill_eggs(mtmp.minvent);
    }

    kill_eggs(C.gi.invent);
    kill_eggs(C.fobj);
    kill_eggs(C.gm.migrating_objs);
    kill_eggs(C.svl.level.buriedobjlist);
}

function golemeffects(mon,damtype,dam)

{
    (damtype = C.int(C.int(damtype))); (dam = C.int(C.int(dam)));
    let heal = C.int(0), slow = C.int(0);

    if (C.samePtr(mon.data, C.mons[C.PM_FLESH_GOLEM])) {
        if ((damtype == C.AD_ELEC))
            (heal = C.int(C.int((C.int((dam) + (5))) / (6))));
        else if ((((damtype == C.AD_FIRE) || (damtype == C.AD_COLD)) ? 1 : 0))
            (slow = C.int(1));
    } else if (C.samePtr(mon.data, C.mons[C.PM_IRON_GOLEM])) {
        if ((damtype == C.AD_ELEC))
            (slow = C.int(1));
        else if ((damtype == C.AD_FIRE))
            (heal = C.int(dam));
    } else {
        return;
    }
    if (slow) {
        if ((mon.mspeed != C.MSLOW))
            C.mon_adjust_speed(mon, -1, 0);
    }
    if (heal) {
        if (healmon(mon, heal, 0)) {
            if (C.cansee(mon.mx, mon.my))
                C.pline_mon(mon, "%s seems healthier.", C.Monnam(mon));
        }
    }
}

/* anger the Minetown watch */
function angry_guards(silent)

{
    (silent = C.char(C.boolean(silent)));
    let mtmp;
    let ct = C.int(0), nct = C.int(0), sct = C.int(0), slct = C.int(0);

    for ((mtmp = C.fmon); mtmp; (mtmp = mtmp.nmon)) {
        if (C.DEADMONSTER(mtmp))
            continue;
        if (((C.is_watch(mtmp.data) && mtmp.mpeaceful) ? 1 : 0)) {
            ct++;
            if (((C.canspotmon(mtmp) && mtmp.mcanmove) ? 1 : 0)) {
                if (C.m_next2u(mtmp))
                    nct++;
                else
                    sct++;
            }
            if (((mtmp.msleeping || mtmp.mfrozen) ? 1 : 0)) {
                slct++;
                (mtmp.msleeping = (mtmp.mfrozen = 0));
            }
            (mtmp.mpeaceful = 0);
        }
    }
    if (ct) {
        if (!silent) { /* do we want pline msgs? */
            const buf=C.stackAlloc(C.BUFSZ);

            if (slct) { /* sleeping guard(s) */
                C.Sprintf(buf, "guard%s", C.plur(slct));
                C.pline_The("%s %s up.", buf, C.vtense(buf, "wake"));
            }

            if (nct) { /* seen/sensed adjacent guard(s) */
                C.Sprintf(buf, "guard%s", C.plur(nct));
                C.pline_The("%s %s angry!", buf, C.vtense(buf, "get"));
            } else if (sct) { /* seen/sensed non-adjacent guard(s) */
                C.Sprintf(buf, "guard%s", C.plur(sct));
                C.pline("%s %s %s approaching!",
                      ((sct == 1) ? "An angry" : "Angry"),
                      buf, C.vtense(buf, "are"));
            } else {
                C.Strcpy(buf, ((ct == 1) ? "a guard's" : "guards'"));
                
                C.You_hear("the shrill sound of %s whistle%s.", buf, C.plur(ct));
            }
        }
        return C.char(1);
    }
    return C.char(0);
}

function pacify_guard(mtmp)

{
    if (C.is_watch(mtmp.data))
        (mtmp.mpeaceful = 1);
}

function pacify_guards()

{
    iter_mons(pacify_guard);
}

function mimic_hit_msg(mtmp,otyp)

{
    (otyp = C.coordxy(C.coordxy(otyp)));
    let ap = C.coordxy(mtmp.mappearance);

    switch (C.M_AP_TYPE(mtmp)) {
    case C.M_AP_NOTHING:
    case C.M_AP_FURNITURE:
    case C.M_AP_MONSTER:
        break;
    case C.M_AP_OBJECT:
        if ((((otyp == C.SPE_HEALING) || (otyp == C.SPE_EXTRA_HEALING)) ? 1 : 0)) {
            C.pline_mon(mtmp, "%s seems a more vivid %s than before.",
                  C.The(C.simple_typename(ap)),
                  C.c_obj_colors[C.objects[ap].oc_color]);
        }
        break;
    }
}

function usmellmon(mdat)

{
    let mndx;
    let nonspecific = C.char(0);
    let msg_given = C.char(0);

    if (mdat) {
        if (!C.olfaction(C.gy.youmonst.data))
            return C.char(0);
        (mndx = C.int(C.monsndx(mdat)));
        switch (mndx) {
        case C.PM_ROTHE:
        case C.PM_MINOTAUR:
            C.You("notice a bovine smell.");
            (msg_given = C.char(1));
            break;
        case C.PM_CAVE_DWELLER:
        case C.PM_BARBARIAN:
        case C.PM_NEANDERTHAL:
            C.You("smell body odor.");
            (msg_given = C.char(1));
            break;
        /*
        case PM_PESTILENCE:
        case PM_FAMINE:
        case PM_DEATH:
            break;
        */
        case C.PM_HORNED_DEVIL:
        case C.PM_BALROG:
        case C.PM_ASMODEUS:
        case C.PM_DISPATER:
        case C.PM_YEENOGHU:
        case C.PM_ORCUS:
            break;
        case C.PM_HUMAN_WEREJACKAL:
        case C.PM_HUMAN_WERERAT:
        case C.PM_HUMAN_WEREWOLF:
        case C.PM_WEREJACKAL:
        case C.PM_WERERAT:
        case C.PM_WEREWOLF:
        case C.PM_OWLBEAR:
            C.You("detect an odor reminiscent of an animal's den.");
            (msg_given = C.char(1));
            break;
        /*
        case PM_PURPLE_WORM:
            break;
        */
        case C.PM_STEAM_VORTEX:
            C.You("smell steam.");
            (msg_given = C.char(1));
            break;
        case C.PM_GREEN_SLIME:
            C.pline("%s stinks.", C.Something);
            (msg_given = C.char(1));
            break;
        case C.PM_VIOLET_FUNGUS:
        case C.PM_SHRIEKER:
            C.You("smell mushrooms.");
            (msg_given = C.char(1));
            break;
        /* These are here to avoid triggering the
           nonspecific treatment through the default case below*/
        case C.PM_WHITE_UNICORN:
        case C.PM_GRAY_UNICORN:
        case C.PM_BLACK_UNICORN:
        case C.PM_JELLYFISH:
            break;
        default:
            (nonspecific = C.char(1));
            break;
        }

        if (nonspecific)
            switch (mdat.mlet) {
            case C.S_DOG:
                C.You("notice a dog smell.");
                (msg_given = C.char(1));
                break;
            case C.S_DRAGON:
                C.You("smell a dragon!");
                (msg_given = C.char(1));
                break;
            case C.S_FUNGUS:
                C.pline("%s smells moldy.", C.Something);
                (msg_given = C.char(1));
                break;
            case C.S_UNICORN:
                C.You("detect a%s odor reminiscent of a stable.",
                    ((mndx == C.PM_PONY) ? "n" : " strong"));
                (msg_given = C.char(1));
                break;
            case C.S_ZOMBIE:
                C.You("smell rotting flesh.");
                (msg_given = C.char(1));
                break;
            case C.S_EEL:
                C.You("smell fish.");
                (msg_given = C.char(1));
                break;
            case C.S_ORC:
                if (((C.Upolyd ? C.is_orc(C.gy.youmonst.data) : C.Race_if(C.PM_ORC))))
                    C.You("notice an attractive smell.");
                else
                    C.pline("A foul stench makes you feel a little nauseated.");
                (msg_given = C.char(1));
                break;
            default:
                break;
            }
    }
    return C.char((msg_given ? 1 : 0));
}

